import{dist}from'./engine.mjs';import{SITES,nearestFloor}from'./lotus-map.mjs';
export const DEVICES={scan:{name:'侦察脉冲',desc:'22米内敌人显形6秒，刷新小地图情报'},med:{name:'急救无人机',desc:'自身与10米内队友恢复35生命'},surge:{name:'超频电容',desc:'自身6秒加速，三个小技能各缩短4秒'}};
export const ORDERS={auto:'自主配合',A:'集结 A',B:'集结 B',C:'集结 C',follow:'跟随我',hold:'守住这里'};
export function issueOrder(game,kind){if(!(kind in ORDERS)||game.winner!==null)return false;const p=game.player;if(p.dead&&['follow','hold'].includes(kind))return false;game.order={kind,x:p.x,z:p.z,at:game.time};if(['A','B','C'].includes(kind))game.planSite=['A','B','C'].indexOf(kind);for(const e of game.entities)if(e.team===0&&!e.player&&e.kind==='hero'){e.path=null;e.task='响应指挥';}game.emit('notice',{text:'战术指令：'+ORDERS[kind]});return true;}
export function orderGoal(game,e){const o=game.order;if(e.team!==0||!o||o.kind==='auto')return null;if(['A','B','C'].includes(o.kind))return SITES[['A','B','C'].indexOf(o.kind)];if(o.kind==='follow'&&!game.player.dead)return nearestFloor({x:game.player.x+(e.slot%2?1:-1)*3,z:game.player.z+(Math.floor(e.slot/2)+1)*2});if(o.kind==='hold')return nearestFloor({x:o.x+(e.slot%2?1:-1)*3,z:o.z+(e.slot-2)*1.7});return null;}
export function tacticalSkills(g,e,target){if(e.think>0||g.status(e,'suppressed'))return;const friends=g.entities.filter(a=>a.kind==='hero'&&a.team===e.team&&!a.dead&&dist(a,e)<10);let choices=[];if(e.hero===4){if(friends.some(a=>a.hp<a.maxHp*.65))choices.push(1);if(target){choices.push(0);if(friends.filter(a=>a.hp<a.maxHp*.75).length>=2)choices.push(3);}}
 else if(e.hero===1){if(e.hp<40)choices.push(0,2);if(target){choices.push(1);if(g.status(target,'marked'))choices.push(3);}}
 else if(target){const d=dist(e,target);if(e.hero===2)choices=d<7?[2,3,0]:[0];if(e.hero===3)choices=d<8?[0,3,2]:[2];if(e.hero===0)choices=e.hp<40?[1,0]:[3,2];}
 for(const i of choices)if(g.cast(e,i))break;e.think=1.3+g.random()*.8;}
export function coverPoint(g,e,threat){let best=null,score=-Infinity;for(let i=0;i<12;i++){const a=i*Math.PI/6,p=nearestFloor({x:e.x+Math.sin(a)*4,z:e.z+Math.cos(a)*4});if(g.blocked(p.x,p.z,e.r,e.team))continue;const s=(!g.los(p,threat,e.team)?20:0)+dist(p,threat)*.3-dist(p,e);if(s>score){score=s;best=p;}}return best;}
